export const ASKING_QUESTIONS_ACTIVITIES = [
// FASE A — FONDASI / KONKRET (1-20): kenapa bertanya, jenis pertanyaan dasar
{n:1,type:"mcq",micro:"Kenapa bertanya",q:"Mengapa bertanya adalah keterampilan penting, bukan tanda bodoh?",options:["Bertanya adalah cara utama belajar, memahami, & menghindari kesalahan; orang yang bertanya justru sedang aktif berpikir","Bertanya berarti kamu tidak memperhatikan","Orang pintar tidak pernah bertanya"],answer:0,explain:"Setiap ahli banyak bertanya. Menyimpan kebingungan diam-diam jauh lebih merugikan daripada bertanya.",hint:"Bertanya = aktif belajar, atau tanda gagal?"},
{n:2,type:"mcq",micro:"Pertanyaan terbuka vs tertutup",q:"'Pertanyaan tertutup' biasanya dijawab...",options:["Dengan cerita panjang","Dengan 'ya', 'tidak', atau satu kata/angka","Tidak bisa dijawab"],answer:1,explain:"Contoh tertutup: 'Kamu suka?' Contoh terbuka: 'Apa yang kamu suka dari itu?' Keduanya berguna untuk tujuan berbeda.",hint:"Jawaban singkat, atau jawaban panjang?"},
{n:3,type:"mcq",micro:"Kegunaan pertanyaan terbuka",q:"Pertanyaan terbuka ('Bagaimana menurutmu?', 'Ceritakan lebih lanjut') berguna untuk...",options:["Mendapat jawaban ya/tidak","Menutup pembicaraan cepat","Mengajak orang bercerita, menjelaskan alasan, & berbagi lebih banyak"],answer:2,explain:"Pertanyaan terbuka membuka percakapan; pertanyaan tertutup memastikan detail. Pakai sesuai kebutuhan.",hint:"Membuka cerita, atau menutup cepat?"},
{n:4,type:"mcq",micro:"Bertanya saat tidak paham",q:"Guru menjelaskan & kamu tidak paham langkah kedua. Sikap terbaik:",options:["Angkat tangan & bertanya spesifik: 'Bu, di langkah kedua kenapa dibagi 3?'","Menyalahkan guru dalam hati","Diam & berharap paham sendiri nanti"],answer:0,explain:"Pertanyaan yang menunjuk bagian spesifik ('langkah kedua') jauh lebih mudah dijawab daripada 'saya nggak ngerti'.",hint:"Diam, atau bertanya spesifik?"},
{n:5,type:"mcq",micro:"Bertanya, bukan menebak",q:"Kamu tidak yakin apakah tugas dikumpulkan hari ini atau besok. Lebih baik...",options:["Menebak & berisiko salah","Bertanya ke guru atau teman untuk memastikan","Tidak mengumpulkan sama sekali"],answer:1,explain:"Satu pertanyaan singkat mencegah kesalahan besar. Menebak hal penting itu berisiko.",hint:"Menebak, atau memastikan dengan bertanya?"},
{n:6,type:"mcq",micro:"Pertanyaan klarifikasi",q:"Temanmu berkata 'nanti kita ketemu di tempat biasa'. Pertanyaan klarifikasi yang baik:",options:["'Oke.' (padahal tidak tahu tempatnya)","'Kenapa kamu selalu nggak jelas?'","'Tempat biasa yang mana? Kantin atau depan gerbang? Jam berapa?'"],answer:2,explain:"Klarifikasi menyebut pilihan konkret & menanyakan detail yang hilang (tempat, waktu).",hint:"Tanya detail yang hilang, atau pura-pura tahu?"},
{n:7,type:"mcq",micro:"Bertanya dengan sopan",q:"Cara sopan menyela untuk bertanya saat orang menjelaskan:",options:["'Maaf, boleh aku tanya sebentar soal bagian tadi?'","Langsung memotong keras: 'Tunggu, apa maksudmu?'","Berbisik ke teman lain, bukan ke pembicara"],answer:0,explain:"Meminta izin singkat + menyebut topik pertanyaan menjaga kesopanan tanpa menahan kebingunganmu.",hint:"Minta izin singkat, atau memotong keras?"},
{n:8,type:"mcq",micro:"Satu pertanyaan sekali",q:"Saat bertanya, menembakkan 5 pertanyaan sekaligus tanpa jeda membuat...",options:["Kamu terlihat sangat pintar","Penjawab bingung harus menjawab yang mana dulu","Jawaban jadi lebih lengkap"],answer:1,explain:"Ajukan satu pertanyaan, dengar jawabannya, baru lanjut. Ini juga membuat kamu benar-benar menyimak jawaban.",hint:"Satu per satu, atau borongan?"},
{n:9,type:"order",micro:"Bertanya di kelas",q:"Urutkan cara bertanya di kelas dengan baik.",items:["Perhatikan sampai penjelasan bagian itu selesai","Rumuskan pertanyaanmu: bagian mana persisnya yang belum jelas","Angkat tangan & tunggu dipersilakan","Ajukan pertanyaan spesifik dengan sopan, lalu simak jawabannya"],answer:[0,1,2,3],explain:"Simak dulu → susun pertanyaan spesifik → angkat tangan → tanya & simak. Bukan langsung menyela dengan 'nggak ngerti'.",hint:"Apa yang dilakukan sebelum mengangkat tangan?"},
{n:10,type:"mcq",micro:"Nada bertanya",q:"'Kenapa kamu melakukan itu?' bisa terdengar menuduh. Agar terdengar seperti rasa ingin tahu:",options:["Nada tinggi menekan tiap kata","Sambil menunjuk & mendekat","Nada tenang & ramah: 'Aku penasaran, apa yang bikin kamu memilih cara itu?'"],answer:2,explain:"Pertanyaan yang sama bisa terasa serangan atau minat, tergantung nada & pilihan kata.",hint:"Nada ingin tahu, atau nada menuduh?"},
{n:11,type:"tf",micro:"Bertanya itu wajar",q:"Benar atau Salah: Mengajukan pertanyaan ketika kamu belum paham adalah hal yang wajar & justru menunjukkan kamu terlibat dalam pelajaran.",answer:true,explain:"Guru umumnya senang ada yang bertanya — itu tanda materi sedang diproses, bukan diabaikan.",hint:"Bertanya = terlibat, atau memalukan?"},
{n:12,type:"tf",micro:"Pertanyaan bodoh",q:"Benar atau Salah: Kalau sebuah pertanyaan terlintas di kepalamu, sebaiknya selalu kamu tahan karena pasti ada yang menganggapnya bodoh.",answer:false,explain:"Sebaliknya, sering kali beberapa orang lain punya pertanyaan yang sama tapi takut bertanya. Pertanyaanmu bisa membantu mereka juga.",hint:"Selalu tahan pertanyaan, atau sering justru membantu banyak orang?"},
{n:13,type:"mcq",micro:"Pertanyaan untuk mengenal orang",q:"Untuk mengenal teman baru, pertanyaan yang membuka obrolan:",options:["'Kegiatan apa yang kamu suka di luar sekolah?'","'Kamu anak orang kaya ya?'","(tidak bertanya apa-apa)"],answer:0,explain:"Pertanyaan terbuka tentang minat terasa ramah & memberi ruang bercerita, bukan menyerang privasi.",hint:"Terbuka & ramah, atau menyinggung?"},
{n:14,type:"mcq",micro:"Bertanya sebelum menyimpulkan",q:"Kamu melihat temanmu tidak membalas pesanmu seharian. Sebelum kesal, sebaiknya...",options:["Menyebarkan bahwa ia sombong","Bertanya: 'Hei, kemarin kamu nggak bales, semuanya oke?'","Menyimpulkan ia sengaja mengabaikanmu & marah"],answer:1,explain:"Bertanya lebih dulu menghindari kesalahpahaman. Mungkin HP-nya rusak atau ia sibuk.",hint:"Tanya dulu, atau simpulkan yang terburuk?"},
{n:15,type:"mcq",micro:"Pertanyaan lanjutan",q:"Teman berkata 'liburan kemarin capek banget'. Pertanyaan lanjutan yang menunjukkan kamu menyimak:",options:["'Oh. Ngomong-ngomong aku kemarin nonton film.'","'Ya semua orang juga capek.'","'Capek gimana? Emang ngapain aja?'"],answer:2,explain:"Pertanyaan lanjutan memakai kata yang baru ia sebut ('capek') untuk menggali lebih dalam.",hint:"Menggali dari ucapannya, atau ganti topik?"},
{n:16,type:"mcq",micro:"Bertanya arah / bantuan",q:"Tersesat di tempat baru, cara bertanya yang efektif:",options:["'Permisi, saya mau ke perpustakaan kota, dari sini lewat mana ya?'","Berputar-putar sendiri tanpa bertanya karena malu","'Perpustakaan di mana?' tanpa menyebut yang mana"],answer:0,explain:"Sapaan sopan + tujuan spesifik + pertanyaan jelas membuat orang mudah membantumu.",hint:"Sapa + tujuan spesifik + pertanyaan jelas, atau malu / tidak spesifik?"},
{n:17,type:"mcq",micro:"Memastikan kamu paham jawaban",q:"Setelah dijawab, kalau kamu masih belum yakin paham:",options:["Bilang 'oke' padahal bingung","'Jadi maksudnya... [ulangi dengan kata sendiri], betul?' untuk memastikan","Menyerah & tidak mengerjakan"],answer:1,explain:"Mengulang jawaban dengan kata-katamu sendiri adalah cara terbaik mengecek pemahaman.",hint:"Pura-pura paham, atau cek dengan mengulang?"},
{n:18,type:"mcq",micro:"Bertanya vs mencari sendiri",q:"Sebelum bertanya hal yang mudah dicari (mis. arti kata umum), sebaiknya...",options:["Selalu langsung bertanya untuk segala hal","Tidak pernah bertanya apa pun","Coba cari sendiri dulu (kamus, buku, catatan); bertanya untuk hal yang benar-benar tidak bisa kamu temukan atau butuh penjelasan"],answer:2,explain:"Menghargai waktu orang: usahakan yang mudah dulu, simpan pertanyaan untuk yang benar-benar butuh bantuan.",hint:"Coba sendiri dulu untuk yang mudah, atau selalu langsung tanya?"},
{n:19,type:"mcq",micro:"Bertanya untuk kejelasan tugas",q:"Diberi tugas 'buat laporan', pertanyaan yang bijak sebelum mulai:",options:["'Berapa panjangnya? Kapan dikumpulkan? Formatnya seperti apa? Boleh berkelompok?'","(mulai kerja & berharap tebakanmu benar)","'Tugasnya susah banget deh.'"],answer:0,explain:"Pertanyaan tentang batasan (panjang, tenggat, format) di awal mencegah kerja ulang.",hint:"Tanya batasan dulu, atau tebak?"},
{n:20,type:"open",micro:"Menyusun pertanyaan yang baik",q:"Kamu bingung tentang tugas proyek kelompok tetapi hanya sempat bertanya 2 pertanyaan ke guru. Tulis 2 pertanyaan yang paling berguna untuk ditanyakan (spesifik, bukan 'saya nggak ngerti'), dan jelaskan mengapa kamu memilih 2 itu.",sample:"Dua pertanyaan: (1) 'Bu, untuk proyek ini, apakah kami boleh memilih topik sendiri atau harus dari daftar yang Ibu berikan?' — karena ini menentukan langkah pertama seluruh kelompok dan tidak bisa ditebak. (2) 'Apa saja yang harus ada di hasil akhir supaya dianggap lengkap — misalnya poster, laporan tertulis, dan presentasi, atau salah satunya saja?' — karena ini menentukan pembagian tugas dan berapa banyak waktu yang kami butuhkan. Aku memilih dua ini karena keduanya adalah hal yang: paling menentukan arah kerja, tidak bisa kami putuskan sendiri, dan kalau salah tebak akan membuat seluruh proyek harus diulang.",explain:"Jawaban baik menghasilkan 2 pertanyaan spesifik & bisa dijawab (bukan 'saya bingung'), yang menyasar hal paling menentukan/tidak bisa ditebak (mis. kebebasan topik, komponen hasil akhir, tenggat, kriteria penilaian), disertai alasan pemilihan (menentukan arah, tidak bisa diputuskan sendiri, mahal kalau salah).",hint:"Pilih pertanyaan tentang hal yang paling menentukan arah kerja dan paling mahal kalau salah tebak."},

// FASE B — PEMAHAMAN (21-40): jenis pertanyaan, pertanyaan menggali, pertanyaan buruk
{n:21,type:"classify",micro:"Pertanyaan membantu vs melukai",q:"Kelompokkan tiap pertanyaan ke 'Membantu/menghargai' atau 'Melukai/menyudutkan'.",items:["'Bagian mana yang bisa aku bantu jelaskan?'","'Kok kamu bego banget sih nggak ngerti?'","'Menurutmu, apa yang bikin ini susah?'","'Emang kamu pikir kamu bisa?'"],groups:["Membantu/menghargai","Melukai/menyudutkan"],answer:{"Membantu/menghargai":["'Bagian mana yang bisa aku bantu jelaskan?'","'Menurutmu, apa yang bikin ini susah?'"],"Melukai/menyudutkan":["'Kok kamu bego banget sih nggak ngerti?'","'Emang kamu pikir kamu bisa?'"]},explain:"Pertanyaan membantu mengundang & menghormati. Pertanyaan menyudutkan menyamar sebagai pertanyaan tapi isinya hinaan.",hint:"Mengundang jawaban jujur, atau menyerang?"},
{n:22,type:"mcq",micro:"Pertanyaan 'mengapa' & 'bagaimana'",q:"Pertanyaan yang dimulai 'mengapa' atau 'bagaimana' cenderung...",options:["Membuat orang tersinggung selalu","Menggali alasan & proses, memancing jawaban yang lebih dalam","Selalu dijawab 'ya/tidak'"],answer:1,explain:"'Apa' & 'kapan' menangkap fakta; 'mengapa' & 'bagaimana' menangkap pemikiran & cara.",hint:"Menggali alasan/proses, atau jawaban singkat?"},
{n:23,type:"mcq",micro:"Pertanyaan mengarahkan (leading)",q:"'Kamu setuju kan kalau ide dia jelek?' adalah pertanyaan mengarahkan karena...",options:["Terlalu terbuka","Netral sepenuhnya","Sudah menyisipkan jawaban yang kamu inginkan, sehingga tidak benar-benar bertanya"],answer:2,explain:"Pertanyaan jujur memberi ruang untuk jawaban apa pun. Pertanyaan mengarahkan menekan orang menyetujuimu.",hint:"Memberi ruang jawaban bebas, atau menekan ke satu jawaban?"},
{n:24,type:"mcq",micro:"Pertanyaan untuk memahami sudut pandang",q:"Saat berdebat & kamu ingin benar-benar mengerti lawan, pertanyaan yang membantu:",options:["'Apa yang membuatmu berpikir begitu? Contohnya seperti apa?'","'Kamu serius mikir gitu?'","'Terserah kamu deh.'"],answer:0,explain:"Bertanya tentang alasan & contoh lawan membuatmu memahami posisi mereka, bukan sekadar menebaknya.",hint:"Menggali alasan mereka, atau meremehkan?"},
{n:25,type:"mcq",micro:"Pertanyaan tertutup yang tepat",q:"Kapan pertanyaan tertutup ('Jadi, kita jadi berangkat jam 7?') paling berguna?",options:["Tidak pernah berguna","Saat kamu perlu memastikan satu fakta atau keputusan dengan cepat & jelas","Saat kamu ingin orang bercerita panjang"],answer:1,explain:"Pertanyaan tertutup mengunci detail & mencegah salah paham. Pertanyaan terbuka membuka; tertutup memastikan.",hint:"Memastikan satu fakta cepat, atau membuka cerita?"},
{n:26,type:"mcq",micro:"Menggali dengan 'lalu apa'",q:"Teknik 'lalu apa yang terjadi?' / 'bisa kasih contoh?' berguna untuk...",options:["Menghentikan orang bercerita","Mengubah topik","Membuat penjelasan orang jadi lebih konkret & lengkap"],answer:2,explain:"Pertanyaan menggali mengubah jawaban umum ('ya, susah') menjadi jawaban spesifik yang berguna.",hint:"Membuat konkret, atau menghentikan?"},
{n:27,type:"tf",micro:"Pertanyaan retoris",q:"Benar atau Salah: 'Pertanyaan retoris' seperti 'Kamu nggak punya otak ya?' bukanlah pertanyaan sungguhan — itu penghinaan yang dibungkus tanda tanya.",answer:true,explain:"Pertanyaan sungguhan mencari jawaban. 'Pertanyaan' yang isinya hinaan atau sindiran bukan bertanya.",hint:"Mencari jawaban, atau menghina?"},
{n:28,type:"tf",micro:"Bertanya = tidak menyimak?",q:"Benar atau Salah: Mengajukan pertanyaan lanjutan yang menyambung dengan cerita seseorang menunjukkan kamu tidak menyimak.",answer:false,explain:"Sebaliknya, pertanyaan lanjutan yang relevan justru bukti kuat bahwa kamu menyimak & memproses ceritanya.",hint:"Pertanyaan nyambung = tidak menyimak?"},
{n:29,type:"mcq",micro:"Pertanyaan yang bisa dijawab",q:"Pertanyaan yang baik biasanya...",options:["Cukup spesifik sehingga penjawab tahu persis apa yang kamu tanyakan","Sangat luas sampai tidak jelas ('jelasin semuanya dong')","Sebenarnya pernyataan yang dipaksa jadi pertanyaan"],answer:0,explain:"'Jelasin semuanya' membebani penjawab. 'Bagian X, kenapa begini?' bisa langsung dijawab.",hint:"Spesifik & terjawab, atau luas & samar?"},
{n:30,type:"order",micro:"Bertanya untuk memahami masalah teman",q:"Urutkan pertanyaan untuk membantu teman yang bilang 'aku stres banget'.",items:["'Stres soal apa? Boleh cerita?'","'Bagian mana yang paling berat buat kamu?'","'Kamu udah coba apa aja sejauh ini?'","'Kamu butuh aku bantu mikir, atau butuh didengar aja?'"],answer:[0,1,2,3],explain:"Dari umum → menyempit → apa yang sudah dicoba → apa yang dibutuhkan. Pertanyaan menuntun tanpa menghakimi.",hint:"Mulai dari pertanyaan yang paling luas atau paling sempit?"},
{n:31,type:"mcq",micro:"Pertanyaan yang menghormati privasi",q:"Batas bertanya yang sopan:",options:["Tidak boleh bertanya apa pun tentang orang lain","Boleh bertanya tentang minat, pendapat, pengalaman umum; hati-hati dengan hal sangat pribadi (keuangan keluarga, masalah rumah) kecuali orangnya membuka sendiri","Boleh bertanya apa saja karena 'cuma nanya'"],answer:1,explain:"'Cuma nanya' tidak menghapus rasa tidak nyaman. Baca apakah orangnya nyaman; berhenti bila ia ragu.",hint:"Ada batas privasi, atau bebas bertanya apa saja?"},
{n:32,type:"tf",micro:"Menyusun pertanyaan lebih dulu",q:"Benar atau Salah: Untuk wawancara atau bertanya ke narasumber, menyiapkan pertanyaan lebih dulu justru membuat percakapan kaku, jadi sebaiknya sepenuhnya spontan.",answer:false,explain:"Sebaliknya, persiapan mencegah kamu lupa hal penting & menjaga arah; kamu tetap bisa mendengarkan jawaban & menambah pertanyaan susulan yang muncul.",hint:"Siapkan pertanyaan dulu, atau sepenuhnya spontan?"},
{n:33,type:"mcq",micro:"Pertanyaan 'salah satu dari' (false dilemma)",q:"'Kamu mau ikut aku atau mau sendirian selamanya?' adalah pertanyaan yang cacat karena...",options:["Terlalu terbuka","Netral","Memaksa memilih hanya dua opsi, padahal ada banyak kemungkinan lain"],answer:2,explain:"Pertanyaan jujur tidak menyembunyikan pilihan. Waspadai pertanyaan yang memaksa dua ekstrem.",hint:"Menyembunyikan opsi lain, atau memberi semua pilihan?"},
{n:34,type:"mcq",micro:"Bertanya di grup chat",q:"Bertanya di grup chat agar mudah dijawab:",options:["Satu pertanyaan jelas per pesan, sebut konteksnya: 'Untuk tugas IPA besok, kita kumpul di kelas mana ya?'","'Ada yang tau nggak?' tanpa menyebut apa","Kirim 10 pertanyaan terpisah beruntun"],answer:0,explain:"Konteks + pertanyaan spesifik = orang bisa langsung menjawab tanpa balik bertanya 'maksudnya apa?'.",hint:"Konteks + spesifik, atau 'ada yang tau nggak'?"},
{n:35,type:"mcq",micro:"Pertanyaan untuk mengecek asumsimu",q:"Kamu berasumsi teman marah padamu. Pertanyaan untuk mengecek:",options:["'Kamu marah kan? Ngaku aja.'","'Aku ngerasa ada yang kurang enak di antara kita. Ada yang bikin kamu kesel nggak?'","(diam & menjauh)"],answer:1,explain:"Pertanyaan terbuka & jujur memberi ruang jawaban apa pun. 'Ngaku aja' sudah menuduh.",hint:"Membuka ruang jawaban, atau menuduh?"},
{n:36,type:"mcq",micro:"Bertanya tanpa menyalahkan",q:"Proyek kelompok terlambat. Pertanyaan yang membantu tim maju (bukan mencari kambing hitam):",options:["'Siapa nih yang bikin telat?'","'Kalian semua nggak becus.'","'Apa yang bikin kita telat, & apa yang bisa kita ubah supaya bagian berikutnya lancar?'"],answer:2,explain:"Pertanyaan berorientasi solusi ('apa yang bisa kita ubah') lebih produktif daripada mencari siapa yang salah.",hint:"Fokus perbaikan, atau fokus menyalahkan?"},
{n:37,type:"tf",micro:"Diam sejenak setelah bertanya",q:"Benar atau Salah: Setelah mengajukan pertanyaan, sebaiknya kamu segera mengisi keheningan dengan menjawab sendiri atau menambah pertanyaan lain agar percakapan tidak canggung.",answer:false,explain:"Sebaliknya, banyak orang butuh jeda untuk menyusun jawaban. Mengisi keheningan terlalu cepat memotong pemikiran mereka & menurunkan mutu jawaban.",hint:"Beri jeda berpikir, atau langsung isi keheningan?"},
{n:38,type:"mcq",micro:"Pertanyaan yang mengundang ide",q:"Dalam diskyci kelompok, pertanyaan yang mengajak semua ikut berpikir:",options:["'Ada yang punya cara lain untuk melihat ini?' / 'Bagaimana kalau kita coba...?'","'Kalian setuju sama aku kan?'","'Udah, ikut aku aja.'"],answer:0,explain:"Pertanyaan terbuka ke kelompok membuka ruang bagi ide yang belum terpikir & membuat anggota merasa dihargai.",hint:"Mengajak semua berpikir, atau menekan setuju?"},
{n:39,type:"mcq",micro:"Kapan berhenti bertanya",q:"Bertanya juga punya batas. Tanda kamu perlu berhenti menggali:",options:["Setelah tepat 3 pertanyaan, selalu","Orang terlihat tidak nyaman, sudah menjawab jelas, atau berkata 'aku belum mau membahas itu'","Tidak ada batas, terus tanya sampai puas"],answer:1,explain:"Bertanya yang baik peka: berhenti saat jawaban sudah cukup atau saat orang menunjukkan tidak nyaman.",hint:"Baca kenyamanan orang, atau tanya terus tanpa henti?"},
{n:40,type:"open",micro:"Memperbaiki pertanyaan buruk",q:"Ubah 3 pertanyaan buruk ini menjadi pertanyaan yang baik, dan jelaskan apa yang kamu perbaiki: (a) 'Kamu ngerti nggak?' (b) 'Kenapa kamu selalu telat?' (c) 'Idenya jelek kan?'",sample:"(a) 'Kamu ngerti nggak?' → 'Coba jelaskan ke aku langkah pertamanya apa?' — perbaikan: mengganti pertanyaan tertutup yang mudah dijawab 'iya' padahal belum paham, dengan pertanyaan yang benar-benar menguji pemahaman. (b) 'Kenapa kamu selalu telat?' → 'Aku perhatiin beberapa kali kamu datang terlambat. Ada yang bikin susah buat berangkat lebih awal?' — perbaikan: membuang kata menuduh 'selalu', menyebut fakta spesifik, dan bertanya dengan nada ingin memahami, bukan menyerang. (c) 'Idenya jelek kan?' → 'Menurutmu, apa kelebihan dan kekurangan ide itu?' — perbaikan: mengubah pertanyaan mengarahkan (yang sudah menyisipkan jawaban) menjadi pertanyaan netral yang mengundang penilaian jujur dari dua sisi.",explain:"Jawaban baik mengubah: (a) tertutup→pertanyaan yang menguji pemahaman nyata; (b) menuduh/'selalu'→fakta spesifik + nada memahami; (c) mengarahkan→netral & mengundang dua sisi; masing-masing dengan penjelasan perbaikannya.",hint:"Ganti 'ngerti nggak' dengan uji pemahaman; buang 'selalu' & tuduhan; hapus jawaban yang disisipkan."},

// FASE C — PENERAPAN (41-60): skenario
{n:41,type:"mcq",micro:"Skenario: bertanya ke guru setelah kelas",q:"Kamu malu bertanya di depan kelas. Alternatif yang baik:",options:["Tidak bertanya sama sekali & menyerah","Menyalin jawaban teman tanpa paham","Menemui guru setelah kelas: 'Bu, tadi bagian pecahan campuran saya masih bingung, boleh dijelaskan sekali lagi?'"],answer:2,explain:"Kalau bertanya di kelas terasa berat, bertanya empat mata setelahnya tetap jauh lebih baik daripada diam.",hint:"Tanya empat mata setelah kelas, atau menyerah?"},
{n:42,type:"mcq",micro:"Skenario: bertanya sebelum membeli",q:"Sebelum membeli barang bekas dari teman, pertanyaan yang bijak:",options:["'Kondisinya bagaimana? Ada yang rusak/kurang? Kenapa dijual? Bisa dicoba dulu?'","(langsung bayar tanpa bertanya)","'Murah nggak?' saja"],answer:0,explain:"Pertanyaan tentang kondisi, kelengkapan, & alasan jual melindungimu dari kekecewaan.",hint:"Tanya kondisi & kelengkapan, atau langsung bayar?"},
{n:43,type:"mcq",micro:"Skenario: klarifikasi instruksi rumit",q:"Ibu menyuruh 'beli bahan buat masak nanti malam' tanpa detail. Pertanyaan agar tidak salah beli:",options:["'Nanti aja deh belinya'","'Masak apa? Bahannya apa aja & berapa banyak? Beli di mana? Uangnya berapa?'","(beli seadanya & berharap benar)"],answer:1,explain:"Instruksi kabur butuh pertanyaan yang mengisi semua bagian yang hilang.",hint:"Isi semua bagian yang hilang, atau tebak?"},
{n:44,type:"mcq",micro:"Skenario: teman menyebut istilah asing",q:"Teman terus memakai singkatan klub yang tidak kamu paham. Sikap yang baik:",options:["Mengangguk pura-pura paham lalu bingung terus","Menegur ia karena 'sok'","'Maaf, 'PJ' itu apa ya? Aku belum tahu istilah-istilah di sini.'"],answer:2,explain:"Bertanya arti istilah di awal mencegah kesalahpahaman menumpuk sepanjang percakapan.",hint:"Tanya artinya, atau pura-pura paham?"},
{n:45,type:"order",micro:"Wawancara narasumber untuk tugas",q:"Urutkan langkah mewawancarai seorang narasumber untuk tugas.",items:["Siapkan 4-5 pertanyaan inti, dari yang mudah ke yang lebih dalam","Mulai dengan pertanyaan ringan untuk mencairkan suasana","Dengar tiap jawaban, ajukan pertanyaan susulan bila ada yang menarik","Tutup dengan 'ada hal lain yang menurut Bapak/Ibu penting saya tahu?' & ucapkan terima kasih"],answer:[0,1,2,3],explain:"Siapkan → mulai ringan → gali dengan susulan → beri ruang tambahan & berterima kasih.",hint:"Apa yang disiapkan sebelum wawancara dimulai?"},
{n:46,type:"mcq",micro:"Skenario: menawarkan bantuan lewat pertanyaan",q:"Teman terlihat kesulitan tapi tidak minta tolong. Pertanyaan yang menawarkan tanpa memaksa:",options:["'Kamu keliatan lagi ribet. Mau aku bantu, atau lebih enak dikerjain sendiri?'","'Sini aku aja yang kerjain semua.'","(mengambil alih tanpa bertanya)"],answer:0,explain:"Menanyakan apakah & bagaimana ia ingin dibantu menghormati kemandiriannya.",hint:"Tanya dulu mau dibantu atau tidak, atau langsung ambil alih?"},
{n:47,type:"mcq",micro:"Skenario: bertanya saat rapat OSIS",q:"Sebuah usul disampaikan cepat & kamu belum paham dampaknya. Pertanyaan yang membantu seluruh rapat:",options:["'Ah, ribet. Skip aja.'","'Boleh dijelaskan, kalau usul ini jalan, apa yang berubah buat siswa biasa?'","(diam & voting asal)"],answer:1,explain:"Pertanyaan klarifikasi di rapat sering membantu banyak orang yang juga belum paham tapi diam.",hint:"Minta penjelasan dampak, atau voting asal?"},
{n:48,type:"mcq",micro:"Skenario: bertanya balik saat dikritik",q:"Guru bilang tulisanmu 'kurang fokus'. Pertanyaan agar kritik itu berguna:",options:["'Jadi maksudnya tulisan saya jelek?'","(diam & kesal)","'Bagian mana yang menurut Bu paling melenceng dari topik? Contohnya?'"],answer:2,explain:"Pertanyaan yang meminta contoh spesifik mengubah kritik umum menjadi arahan yang bisa kamu kerjakan.",hint:"Minta contoh spesifik, atau tersinggung?"},
{n:49,type:"mcq",micro:"Skenario: bertanya ke orang tua soal keputusan",q:"Kamu ingin ikut kegiatan yang butuh izin orang tua. Cara bertanya yang matang:",options:["Jelaskan kegiatannya, lalu tanya: 'Menurut Ayah/Ibu, apa yang perlu aku siapkan atau pikirkan sebelum ikut?'","'Pokoknya aku mau ikut, boleh ya?'","(ikut diam-diam tanpa bertanya)"],answer:0,explain:"Bertanya tentang pertimbangan mereka (bukan sekadar 'boleh/tidak') menunjukkan kedewasaan & membuka diskusi.",hint:"Tanya pertimbangan mereka, atau memaksa / diam-diam?"},
{n:50,type:"open",micro:"Menyusun daftar pertanyaan",q:"Kamu akan menjadi anggota baru sebuah ekskul dan diberi kesempatan bertanya ke ketua. Tulis 4 pertanyaan yang benar-benar berguna untuk anggota baru, dan urutkan dari yang paling penting. Jelaskan singkat kenapa urutannya begitu.",sample:"Daftar pertanyaan (urut dari paling penting): (1) 'Kapan dan di mana jadwal latihan/pertemuan rutinnya?' — paling penting karena menentukan apakah aku bisa berkomitmen sama sekali. (2) 'Apa yang diharapkan dari anggota baru dalam sebulan pertama — misalnya kehadiran, tugas, atau bawa perlengkapan apa?' — penting supaya aku tahu cara memulai dengan benar. (3) 'Bagaimana biasanya anggota baru belajar dan siapa yang bisa aku tanyai kalau bingung?' — supaya aku tahu jalur bantuan. (4) 'Apa kegiatan besar atau target ekskul ini dalam waktu dekat?' — berguna untuk gambaran arah, tapi bisa ditanyakan belakangan karena tidak mendesak. Urutannya dari yang menentukan keikutsertaan dan langkah awal, ke yang sekadar menambah gambaran.",explain:"Jawaban baik menghasilkan 4 pertanyaan konkret & berguna untuk anggota baru (jadwal, ekspektasi awal, jalur bantuan, arah/kegiatan), diurutkan dengan alasan (mendahulukan yang menentukan komitmen & langkah pertama, menaruh yang sekadar gambaran di belakang).",hint:"Dahulukan pertanyaan yang menentukan apakah & bagaimana kamu mulai; taruh yang 'nice to know' di belakang."},
{n:51,type:"mcq",micro:"Skenario: pertanyaan menjebak dari teman",q:"Teman bertanya 'Kamu lebih milih aku atau si Doni jadi teman?' untuk memancing drama. Respons yang baik:",options:["Menghindari teman itu selamanya","'Aku nggak mau milih-milih teman. Kenapa kamu nanya gitu?'","Menjawab salah satu nama & memicu konflik"],answer:1,explain:"Kamu boleh menolak menjawab pertanyaan yang dirancang menyakiti, & balik bertanya alasannya.",hint:"Tolak jebakan + tanya alasan, atau ikut memilih?"},
{n:52,type:"tf",micro:"Bertanya menghemat waktu",q:"Benar atau Salah: Meluangkan waktu bertanya untuk memastikan instruksi yang tidak jelas biasanya lebih hemat daripada langsung mengerjakan berdasarkan tebakan lalu harus mengulang.",answer:true,explain:"Satu menit bertanya bisa menghemat berjam-jam kerja ulang. 'Ukur dua kali, potong sekali.'",hint:"Bertanya dulu, atau kerjakan-ulang?"},
{n:53,type:"mcq",micro:"Skenario: bertanya ke kakak kelas",q:"Kamu ingin tips dari kakak kelas yang jago di bidang tertentu. Pertanyaan yang menghargai waktunya:",options:["'Kak, ajarin aku semuanya dong dari nol.'","'Kak jago ya?' tanpa pertanyaan lanjutan","Pertanyaan spesifik: 'Kak, waktu awal belajar coding, sumber apa yang paling ngebantu buat pemula?'"],answer:2,explain:"Pertanyaan spesifik & terfokus mudah dijawab & menunjukkan kamu sudah memikirkannya.",hint:"Spesifik & fokus, atau 'ajarin semuanya'?"},
{n:54,type:"mcq",micro:"Skenario: memastikan janji",q:"Kamu & teman berencana bertemu tapi detailnya samar. Pesan pemastian:",options:["'Konfirmasi ya: besok (Sabtu) jam 9 pagi di depan perpustakaan kota. Betul?'","'Besok ketemu ya' (tanpa detail)","Tidak mengonfirmasi & berharap sama-sama ingat"],answer:0,explain:"Pertanyaan pemastian yang menyebutkan semua detail (hari, jam, tempat) mencegah salah janji.",hint:"Konfirmasi semua detail, atau 'besok ketemu ya'?"},
{n:55,type:"mcq",micro:"Skenario: bertanya untuk menolong yang sedih",q:"Teman terlihat murung. Pembuka yang lembut:",options:["'Jangan sedih ah.'","'Kamu kelihatan lagi nggak enak. Mau cerita, atau lebih baik aku temenin diam aja dulu?'","'Kenapa? Ada apa? Cerita dong cepetan!'"],answer:1,explain:"Pertanyaan yang menawarkan pilihan (cerita atau ditemani) menghormati kesiapan orang.",hint:"Menawarkan pilihan lembut, atau mendesak / menutup?"},
{n:56,type:"mcq",micro:"Skenario: pertanyaan saat presentasi orang lain",q:"Setelah teman presentasi, pertanyaan yang membangun:",options:["'Presentasimu membosankan ya.'","(tidak bertanya karena malas)","'Bagian idemu soal daur ulang menarik — bagaimana kalau di sekolah yang tidak punya tempat sampah terpisah?'"],answer:2,explain:"Pertanyaan yang menyebut bagian spesifik + mengembangkan pemikirannya menghargai kerja presenter.",hint:"Kembangkan idenya, atau meremehkan?"},
{n:57,type:"tf",micro:"Bertanya balik itu boleh",q:"Benar atau Salah: Ketika seseorang mengajukan pertanyaan yang tidak jelas maksudnya, kamu sebaiknya langsung menjawab tebakan terbaikmu daripada meminta ia memperjelas dulu.",answer:false,explain:"Sebaliknya, menjawab pertanyaan yang salah kamu pahami membuang waktu keduanya. Meminta klarifikasi ('Maksudmu bagian yang mana?') dulu adalah hal yang wajar.",hint:"Perjelas dulu, atau jawab tebakan?"},
{n:58,type:"mcq",micro:"Skenario: bertanya untuk mengecek keamanan",q:"Seseorang online mengajak bertemu langsung. Pertanyaan & sikap yang aman:",options:["Tanyakan ke orang tua/orang dewasa tepercaya dulu, & jangan bertemu orang asing dari internet tanpa pendampingan","Langsung tanya lokasi & pergi sendiri","Bertanya detail pribadimu ke orang itu"],answer:0,explain:"Pertanyaan terpenting di sini bukan ke orang asing itu, melainkan ke orang dewasa tepercaya tentang keamanannya.",hint:"Tanya orang dewasa tepercaya dulu, atau pergi sendiri?"},
{n:59,type:"mcq",micro:"Skenario: bertanya vs menyebar gosip",q:"Kamu dengar rumor bahwa temanmu pindah sekolah. Yang benar:",options:["Mendiamkannya & memperlakukan teman berbeda","Bertanya langsung ke temannya dengan sopan: 'Aku dengar kamu mau pindah, beneran?'","Menyebarkan rumor itu ke orang lain"],answer:1,explain:"Bertanya langsung ke sumbernya menghentikan rumor & menghormati temanmu.",hint:"Tanya langsung ke sumbernya, atau sebar / diam?"},
{n:60,type:"open",micro:"Skenario menyeluruh",q:"Kelompokmu harus membuat video pendek, tapi arahan dari guru terdengar samar dan waktu bertanya terbatas. Rancang: 3 pertanyaan yang akan kamu ajukan ke guru, 2 pertanyaan yang akan kamu diskusikan di dalam kelompok, dan jelaskan mengapa kamu membagi pertanyaan seperti itu.",sample:"Pertanyaan untuk GURU (hal yang hanya guru bisa jawab): (1) 'Berapa durasi video yang diharapkan, dan kapan tenggat pengumpulannya?' (2) 'Apa kriteria penilaiannya — lebih ke isi, kreativitas, atau kualitas rekaman?' (3) 'Bolehkah kami merekam di luar jam sekolah dan memakai musik dari internet?' Pertanyaan untuk KELOMPOK (hal yang kami putuskan sendiri): (4) 'Topik atau sudut cerita apa yang mau kita ambil?' (5) 'Siapa mengerjakan apa — naskah, rekaman, edit — dan kapan tiap bagian selesai?' Alasan pembagian: pertanyaan ke guru adalah hal yang menentukan batas dan aturan yang tidak bisa kami tebak atau putuskan sendiri, dan kalau salah tebak bisa membuat seluruh video harus diulang. Pertanyaan kelompok adalah keputusan internal yang justru lebih baik kami bahas bersama supaya semua ikut memiliki, dan menanyakannya ke guru hanya membuang jatah waktu bertanya yang terbatas.",explain:"Jawaban baik memisahkan pertanyaan berdasarkan siapa yang bisa/berhak menjawab: ke guru untuk batasan & aturan yang tak bisa ditebak (durasi, tenggat, kriteria, izin), ke kelompok untuk keputusan internal (topik, pembagian tugas), dengan alasan yang menyebut efisiensi waktu bertanya & rasa kepemilikan tim.",hint:"Tanyakan ke guru hanya hal yang cuma guru tahu / tetapkan; sisakan keputusan tim untuk dibahas bersama."},

// FASE D — PENALARAN (61-80)
{n:61,type:"mcq",micro:"Mengapa pertanyaan mendorong berpikir",q:"Mengapa guru sering menjawab pertanyaan dengan pertanyaan balik ('Menurutmu kenapa?')?",options:["Karena guru tidak tahu jawabannya","Untuk menghindari membantu","Untuk membantumu menemukan jawaban sendiri, yang membuat pemahamanmu lebih kuat & tahan lama"],answer:2,explain:"Jawaban yang kamu temukan sendiri (dengan bimbingan pertanyaan) lebih melekat daripada yang sekadar diberikan.",hint:"Membimbingmu menemukan sendiri, atau menghindar?"},
{n:62,type:"mcq",micro:"Pertanyaan & kualitas keputusan",q:"Sebelum mengambil keputusan penting, mengajukan pertanyaan seperti 'Apa risikonya? Apa alternatifnya? Apa yang aku lewatkan?' membantu karena...",options:["Menemukan masalah & pilihan yang belum terpikir sebelum kamu terlanjur","Membuat keputusan jadi lebih lambat tanpa manfaat","Selalu membuat bingung"],answer:0,explain:"Pertanyaan yang tepat adalah alat berpikir. Keputusan yang tidak pernah dipertanyakan sering menyimpan lubang.",hint:"Menemukan lubang sebelum terlambat, atau memperlambat sia-sia?"},
{n:63,type:"tf",micro:"Pertanyaan menunjukkan keterlibatan",q:"Benar atau Salah: Dalam banyak situasi belajar & kerja, orang yang mengajukan pertanyaan bagus dipandang lebih terlibat & lebih serius, bukan kurang mampu.",answer:true,explain:"Pertanyaan yang matang menunjukkan kamu sudah memikirkan materi cukup dalam untuk tahu apa yang belum kamu ketahui.",hint:"Pertanyaan bagus = terlibat, atau kurang mampu?"},
{n:64,type:"mcq",micro:"Menilai pertanyaan yang menyesatkan",q:"Di media sosial, pertanyaan seperti 'Kenapa media tidak memberitakan [klaim tak terbukti] ini?' bisa menyesatkan karena...",options:["Terlalu spesifik","Menyisipkan asumsi belum terbukti (bahwa klaimnya benar) ke dalam pertanyaan, seolah sudah pasti","Terlalu netral"],answer:1,explain:"Pertanyaan bisa menyelundupkan asumsi. Periksa: apakah pertanyaan ini menganggap sesuatu benar tanpa bukti?",hint:"Menyelundupkan asumsi tak terbukti, atau netral?"},
{n:65,type:"mcq",micro:"Pertanyaan terbuka vs tertutup: memilih",q:"Kamu ingin tahu perasaan teman tentang pindah rumah. Pertanyaan yang lebih tepat:",options:["Tertutup: 'Kamu sedih nggak?' (memaksa satu emosi)","Mengarahkan: 'Pasti berat banget kan?'","Terbuka: 'Gimana perasaanmu soal pindahan ini?'"],answer:2,explain:"Untuk menggali perasaan, pertanyaan terbuka memberi ruang; pertanyaan tertutup/mengarahkan membatasi jawaban.",hint:"Terbuka untuk perasaan, atau memaksa satu emosi?"},
{n:66,type:"tf",micro:"Semua pertanyaan sama nilainya?",q:"Benar atau Salah: Semua pertanyaan sama baiknya; tidak ada yang namanya pertanyaan yang disusun dengan buruk.",answer:false,explain:"Sebaliknya, pertanyaan bisa buruk: terlalu kabur, mengarahkan, menyudutkan, menyelundupkan asumsi, atau memaksa dua pilihan palsu. Cara bertanya bisa dilatih menjadi lebih baik.",hint:"Semua pertanyaan setara, atau ada yang cacat?"},
{n:67,type:"mcq",micro:"Pertanyaan & rasa aman kelompok",q:"Ketika seorang pemimpin rutin bertanya 'Ada yang kurang jelas?' & menyambut pertanyaan dengan ramah, efeknya pada tim:",options:["Anggota merasa aman bertanya, sehingga masalah ketahuan lebih awal","Anggota jadi malas berpikir sendiri","Tidak ada efek"],answer:0,explain:"Budaya di mana bertanya aman = masalah kecil terungkap sebelum jadi besar.",hint:"Masalah ketahuan dini, atau anggota jadi malas?"},
{n:68,type:"mcq",micro:"Menyeimbangkan bertanya & mendengarkan",q:"Percakapan yang sehat biasanya...",options:["Tanpa pertanyaan sama sekali","Menyeimbangkan bertanya (menunjukkan minat) & benar-benar menyimak jawabannya, bukan menembakkan pertanyaan seperti interogasi","Berisi pertanyaan bertubi tanpa jeda menyimak"],answer:1,explain:"Bertanya tanpa menyimak jawaban terasa seperti diinterogasi. Pertanyaan adalah undangan, bukan tembakan.",hint:"Tanya + simak, atau tembakan pertanyaan?"},
{n:69,type:"mcq",micro:"Pertanyaan untuk memeriksa informasi",q:"Saat mendengar klaim mengejutkan, pertanyaan yang membantu menilainya:",options:["'Siapa yang bilang? Ah pasti bohong.'","(langsung percaya & sebarkan)","'Sumbernya dari mana? Kapan? Apa ada yang membantah? Bagaimana mereka tahu?'"],answer:2,explain:"Pertanyaan tentang sumber, waktu, & cara mengetahui adalah alat dasar memeriksa kebenaran.",hint:"Tanya sumber & bukti, atau langsung percaya / tolak?"},
{n:70,type:"order",micro:"Dari bingung ke pertanyaan tajam",q:"Urutkan cara mengubah kebingungan menjadi pertanyaan yang tajam.",items:["Sadari & akui: 'Ada bagian yang belum aku mengerti'","Persempit: bagian mana persisnya? kata/langkah/konsep apa?","Cek dulu: sudahkah aku coba cari di catatan/buku?","Rumuskan pertanyaan spesifik yang bisa dijawab, lalu ajukan"],answer:[0,1,2,3],explain:"Akui → persempit → cek sendiri → rumuskan spesifik. 'Aku nggak ngerti' berubah jadi 'di langkah 3, kenapa X?'.",hint:"Apa langkah sebelum bisa merumuskan pertanyaan spesifik?"},
{n:71,type:"mcq",micro:"Mengapa 'pertanyaan bodoh' jarang benar-benar bodoh",q:"Sebuah 'pertanyaan dasar' di rapat sering bernilai karena...",options:["Memeriksa apakah semua orang benar-benar sepaham tentang hal mendasar yang mungkin diasumsikan begitu saja","Selalu membuang waktu","Membuat penanya terlihat lemah"],answer:0,explain:"Banyak kesalahan besar berasal dari asumsi dasar yang tidak pernah diperiksa karena 'kan sudah jelas'.",hint:"Memeriksa asumsi dasar, atau membuang waktu?"},
{n:72,type:"tf",micro:"Bertanya bisa dilatih",q:"Benar atau Salah: Kemampuan mengajukan pertanyaan yang jelas, spesifik, & tidak menyudutkan bisa ditingkatkan dengan latihan & memperhatikan pertanyaan orang yang pandai bertanya.",answer:true,explain:"Perhatikan bagaimana guru atau pewawancara yang baik bertanya, lalu tiru pola yang membuat orang mau menjawab.",hint:"Bawaan, atau bisa dilatih & ditiru?"},
{n:73,type:"mcq",micro:"Pertanyaan yang membangun vs merobohkan",q:"Dalam diskusi, pertanyaan yang membangun ide teman:",options:["'Ganti aja idenya.'","'Kalau kita kembangkan idemu, bagaimana mengatasi kendala X?'","'Idemu nggak mungkin jalan, ngapain dibahas?'"],answer:1,explain:"Pertanyaan membangun menganggap ide layak dikembangkan & mengajak berpikir bersama mengatasi kendalanya.",hint:"Mengembangkan bersama, atau merobohkan?"},
{n:74,type:"mcq",micro:"Kapan pertanyaan jadi tidak sopan",q:"Pertanyaan bisa terasa tidak sopan bila...",options:["Spesifik & jelas","Diajukan dengan nada ramah","Menuntut informasi sangat pribadi, diajukan di depan umum yang mempermalukan, atau bernada menghakimi"],answer:2,explain:"Isi (privasi), tempat (di depan umum), & nada (menghakimi) semua bisa membuat pertanyaan menyakiti.",hint:"Privasi + di depan umum + menghakimi, atau spesifik + ramah?"},
{n:75,type:"tf",micro:"Pertanyaan mengarahkan dalam survei",q:"Benar atau Salah: Dalam survei, pertanyaan yang disusun agar responden condong menjawab dengan cara tertentu ('Setujukah Anda bahwa kebijakan buruk ini harus dihentikan?') tetap menghasilkan data yang jujur & bisa dipercaya.",answer:false,explain:"Sebaliknya, pertanyaan mengarahkan menyisipkan penilaian sehingga hasil survei jadi bias & tidak bisa dipercaya. Pertanyaan yang baik dibuat netral.",hint:"Menyisipkan penilaian ke pertanyaan — data jujur atau bias?"},
{n:76,type:"mcq",micro:"Pertanyaan reflektif untuk diri sendiri",q:"Bertanya pada diri sendiri ('Apa yang sebenarnya aku takutkan di sini? Apa buktinya?') berguna karena...",options:["Membantumu memahami perasaan & memeriksa apakah kekhawatiranmu berdasar","Membuat kamu lebih cemas selalu","Tidak ada gunanya bertanya ke diri sendiri"],answer:0,explain:"Pertanyaan yang baik juga alat untuk memahami diri, bukan hanya orang lain.",hint:"Memahami & memeriksa diri, atau menambah cemas?"},
{n:77,type:"mcq",micro:"Pertanyaan & belajar seumur hidup",q:"Orang yang terus mengajukan pertanyaan sepanjang hidupnya cenderung...",options:["Berhenti berkembang","Terus belajar & menyesuaikan diri, karena mereka tidak menganggap sudah tahu segalanya","Tampak bodoh"],answer:1,explain:"Rasa ingin tahu yang dijaga lewat bertanya adalah mesin belajar seumur hidup.",hint:"Terus belajar, atau berhenti berkembang?"},
{n:78,type:"mcq",micro:"Menilai jawaban lewat pertanyaan lanjutan",q:"Seseorang memberi jawaban yang terdengar meyakinkan tapi umum. Pertanyaan lanjutan yang menguji:",options:["'Oke, aku percaya.'","'Kamu ngarang ya?'","'Bisa kasih contoh nyata? Dari mana kamu tahu itu? Apa ada kasus di mana itu tidak berlaku?'"],answer:2,explain:"Pertanyaan tentang contoh, sumber, & pengecualian membantu membedakan pemahaman nyata dari sekadar kata-kata bagus.",hint:"Uji dengan contoh/sumber/pengecualian, atau langsung percaya/tuduh?"},
{n:79,type:"mcq",micro:"Pertanyaan sebagai jembatan",q:"Saat dua orang berselisih, seorang penengah yang baik sering...",options:["Mengajukan pertanyaan yang membantu tiap pihak menjelaskan & memahami sisi lain ('Apa yang paling kamu butuhkan di sini?')","Bertanya 'siapa yang mulai duluan?'","Tidak bertanya apa pun, langsung memutuskan"],answer:0,explain:"Pertanyaan yang tepat membuka pemahaman & sering menemukan kebutuhan bersama yang tersembunyi di balik pertengkaran.",hint:"Pertanyaan yang membuka pemahaman, atau mencari siapa yang salah?"},
{n:80,type:"open",micro:"Menganalisis pertanyaan bermasalah",q:"Seorang pembawa acara bertanya kepada tamunya: 'Jadi, Anda mengakui bahwa program Anda gagal total dan merugikan banyak orang, bukan?' Jelaskan minimal 3 masalah dengan pertanyaan ini, lalu tulis versi yang lebih adil.",sample:"Masalah: (1) Menyelundupkan asumsi yang belum terbukti ke dalam pertanyaan — bahwa program 'gagal total' dan 'merugikan banyak orang' — seolah itu sudah fakta. (2) Mengarahkan: kata 'mengakui' dan 'bukan?' menekan tamu untuk menyetujui bingkai negatif; jawaban 'tidak' pun akan terdengar seperti mengelak. (3) Menggabungkan beberapa klaim jadi satu ('gagal total' DAN 'merugikan banyak orang') sehingga tidak bisa dijawab dengan jelas — ini pertanyaan bertumpuk. (4) Nadanya menghakimi, bukan menggali. Versi yang lebih adil: 'Bagaimana Anda menilai hasil program ini sejauh ini? Bagian mana yang menurut Anda berjalan sesuai harapan, dan bagian mana yang tidak?' — ini netral, tidak menyisipkan kesimpulan, dan memisahkan pertanyaan sehingga bisa dijawab jujur.",explain:"Jawaban baik menyebut minimal 3 masalah (asumsi terselubung/premis belum terbukti, pertanyaan mengarahkan, pertanyaan bertumpuk/menggabung klaim, nada menghakimi) lalu menawarkan versi netral yang tidak menyisipkan kesimpulan & memisahkan pertanyaan.",hint:"Cari asumsi yang diselundupkan, kata yang menekan ke satu jawaban, dan beberapa klaim yang ditumpuk jadi satu."},

// FASE E — TANTANGAN (81-100)
{n:81,type:"mcq",micro:"Kasus: bertanya ke orang yang lebih tahu tanpa merasa kecil",q:"Kamu pemula & bertanya ke ahli. Sikap yang sehat:",options:["Tidak bertanya & tetap tidak paham","Bertanya dengan jujur & spesifik; menjadi pemula bukan aib, & pertanyaan yang baik justru dihormati ahli","Berpura-pura sudah tahu & bertanya samar-samar"],answer:1,explain:"Ahli umumnya senang membantu orang yang benar-benar ingin belajar & bertanya dengan jelas.",hint:"Jujur & spesifik, atau pura-pura tahu?"},
{n:82,type:"mcq",micro:"Kasus: pertanyaan saat kamu curiga dibohongi",q:"Kamu curiga penjual online tidak jujur soal barang. Pertanyaan yang bijak:",options:["Langsung menuduh 'kamu penipu ya?'","Membeli saja & berharap","Minta detail yang bisa diperiksa: 'Boleh minta foto asli kondisi terkini + video? Garansinya apa? Bisa COD/rekber?'"],answer:2,explain:"Pertanyaan yang meminta bukti konkret & perlindungan transaksi jauh lebih berguna daripada tuduhan atau kepasrahan.",hint:"Minta bukti & perlindungan, atau menuduh / pasrah?"},
{n:83,type:"tf",micro:"Refleksi: pertanyaan membentuk percakapan",q:"Benar atau Salah: Jenis pertanyaan yang kamu ajukan sangat memengaruhi arah & kualitas percakapan — pertanyaan yang menghakimi menutup, pertanyaan yang penasaran membuka.",answer:true,explain:"Kamu ikut mengarahkan percakapan lewat pertanyaanmu. Pilih pertanyaan yang membuka pintu, bukan yang membanting.",hint:"Pertanyaan menentukan arah, atau netral saja?"},
{n:84,type:"mcq",micro:"Kasus: satu kesempatan bertanya",q:"Kamu bertemu tokoh yang kamu kagumi & hanya punya waktu satu pertanyaan. Yang terbaik:",options:["Pertanyaan spesifik & bermakna yang hanya bisa dijawab olehnya, mis. 'Keputusan tersulit apa di awal karier Anda, & bagaimana Anda memutuskannya?'","'Gimana caranya sukses?' (terlalu luas)","'Boleh foto?' (menyia-nyiakan kesempatan bertanya)"],answer:0,explain:"Dengan satu kesempatan, pilih pertanyaan yang dalam, personal, & tidak bisa dijawab dari sumber umum mana pun.",hint:"Spesifik & hanya ia bisa jawab, atau umum & bisa dicari sendiri?"},
{n:85,type:"order",micro:"Membantu adik lewat pertanyaan (bukan jawaban)",q:"Urutkan cara membantu adik mengerjakan soal tanpa langsung memberi jawaban.",items:["'Coba baca lagi soalnya. Yang ditanya apa?'","'Kamu tahu apa dari soal ini? Angka atau info apa yang diberikan?'","'Kira-kira langkah pertama untuk menghubungkan yang diketahui ke yang ditanya, apa?'","'Coba kerjakan langkahmu, nanti kita cek bareng.'"],answer:[0,1,2,3],explain:"Pahami yang ditanya → data yang ada → langkah menghubungkan → kerjakan & cek. Pertanyaan menuntun adik berpikir sendiri.",hint:"Mulai dari memahami soal, atau langsung ke langkah akhir?"},
{n:86,type:"mcq",micro:"Kasus: pertanyaan yang tidak nyaman dari orang lain",q:"Seseorang bertanya hal sangat pribadi yang tidak ingin kamu jawab. Respons yang boleh:",options:["Marah & menyerang balik","'Itu agak pribadi buat aku, jadi aku pilih nggak cerita ya.'","Berbohong panjang lebar"],answer:1,explain:"Kamu berhak tidak menjawab pertanyaan tanpa perlu berbohong atau bertengkar. Menolak dengan sopan itu cukup.",hint:"Menolak sopan, atau bohong / menyerang?"},
{n:87,type:"tf",micro:"Pertanyaan & kepercayaan diri",q:"Benar atau Salah: Keberanian bertanya di situasi besar tidak ada hubungannya dengan latihan bertanya di situasi kecil sehari-hari.",answer:false,explain:"Sebaliknya, keberanian bertanya tumbuh seperti otot: dari banyak pengulangan kecil yang berhasil (bertanya harga, arah, ke guru setelah kelas).",hint:"Latihan kecil membangun keberanian besar?"},
{n:88,type:"mcq",micro:"Kasus: memimpin diskusi lewat pertanyaan",q:"Sebagai pemimpin diskusi, cara memastikan semua ikut bicara:",options:["Hanya bertanya ke teman dekatmu","Menjawab semua pertanyaanmu sendiri","Ajukan pertanyaan terbuka ke seluruh grup, lalu undang yang belum bicara: 'Rani, menurutmu bagaimana?' tanpa memaksa"],answer:2,explain:"Pertanyaan terbuka + undangan lembut ke yang diam membuka partisipasi merata.",hint:"Undang yang diam dengan lembut, atau hanya teman dekat?"},
{n:89,type:"mcq",micro:"Kasus: pertanyaan untuk klarifikasi konflik",q:"Dua temanmu bertengkar & kamu menengahi. Pertanyaan yang membantu:",options:["Ke masing-masing: 'Apa yang sebenarnya kamu butuhkan supaya ini beres?' & 'Bisa ulang apa yang kamu dengar dari dia?'","'Siapa yang salah?'","'Kalian berdua nyebelin, kan?'"],answer:0,explain:"Pertanyaan tentang kebutuhan & pemahaman timbal balik menggeser dari 'siapa menang' ke 'bagaimana beres'.",hint:"Tanya kebutuhan & pemahaman, atau cari yang salah?"},
{n:90,type:"open",micro:"Kasus menyeluruh",q:"Kamu ingin memutuskan apakah akan pindah ke kelas peminatan yang berbeda tahun depan. Tulis daftar minimal 6 pertanyaan yang akan kamu ajukan — sebutkan kepada siapa tiap pertanyaan (diri sendiri, orang tua, guru BK/wali kelas, kakak kelas di peminatan itu) — dan jelaskan mengapa bertanya ke berbagai pihak lebih baik daripada satu.",sample:"Ke DIRI SENDIRI: (1) 'Apa alasan sebenarnya aku ingin pindah — minat pada materinya, atau menghindari sesuatu di kelas sekarang?' (2) 'Bagaimana perasaanku membayangkan diri di kelas itu setahun ke depan?' Ke ORANG TUA: (3) 'Apa harapan dan kekhawatiran kalian kalau aku pindah, dan apakah ada pertimbangan biaya atau logistik?' Ke GURU BK / WALI KELAS: (4) 'Apa syarat dan konsekuensi administratif pindah peminatan, dan apakah nilai saya memenuhi?' (5) 'Menurut Bapak/Ibu, dari yang Bapak/Ibu lihat, apa kekuatan dan kelemahan saya yang relevan dengan peminatan itu?' Ke KAKAK KELAS DI PEMINATAN ITU: (6) 'Bagaimana sebenarnya sehari-hari belajar di sana — beban tugas, gaya mengajar, hal yang tak terduga?' (7) 'Apa yang kakak harap seseorang beri tahu sebelum masuk peminatan ini?' Mengapa banyak pihak lebih baik: tiap pihak melihat dari sudut berbeda dan tahu hal yang lain tidak tahu — diriku tahu perasaanku, orang tua tahu kondisi keluarga, guru BK tahu aturan dan menilai kemampuanku secara netral, kakak kelas tahu kenyataan sehari-hari yang tidak ada di brosur. Mengandalkan satu sumber berisiko membuat keputusan berdasar gambaran yang timpang.",explain:"Jawaban baik memuat minimal 6 pertanyaan yang dipetakan ke pihak berbeda (diri: motivasi & perasaan; orang tua: harapan/kekhawatiran/logistik; guru BK: aturan & penilaian kemampuan; kakak kelas: realita sehari-hari) DAN menjelaskan bahwa multi-sumber menutup titik buta karena tiap pihak tahu hal berbeda.",hint:"Petakan pertanyaan ke siapa yang paling tahu jawabannya; jelaskan bahwa tiap sumber menutup titik buta yang lain."},
{n:91,type:"mcq",micro:"Kasus: pertanyaan yang menyaru sebagai serangan di chat",q:"Seseorang membalas argumenmu dengan 'Emang kamu ngerti apa sih soal ini?'. Ini sebenarnya...",options:["Alasan untuk membalas menghina","Bukan pertanyaan tulus, melainkan serangan pribadi; kamu bisa mengarahkan kembali ke isi: 'Kalau ada bagian argumenku yang keliru, bagian mana?'","Pertanyaan bagus yang harus kamu jawab dengan CV-mu"],answer:1,explain:"Kembalikan percakapan ke substansi. Pertanyaan yang isinya serangan pribadi tidak wajib dijawab pada tingkatnya.",hint:"Serangan menyaru pertanyaan — kembalikan ke isi, atau ikut menghina?"},
{n:92,type:"tf",micro:"Refleksi: pertanyaan sebelum jawaban",q:"Benar atau Salah: Sering kali, mengajukan pertanyaan yang tepat lebih berharga daripada langsung memberi jawaban, karena pertanyaan yang tepat membuka jalan ke banyak jawaban.",answer:true,explain:"'Jawaban yang benar untuk pertanyaan yang salah tidak berguna.' Menemukan pertanyaan yang tepat adalah setengah dari pemecahan masalah.",hint:"Pertanyaan tepat, atau jawaban cepat?"},
{n:93,type:"mcq",micro:"Kasus: menahan diri untuk tidak bertanya",q:"Kapan lebih baik TIDAK bertanya (menahan pertanyaan)?",options:["Tidak pernah — selalu tanyakan semuanya","Selalu tahan semua pertanyaan","Saat pertanyaan itu bisa kamu jawab sendiri dengan sedikit usaha, saat sangat tidak tepat waktunya, atau saat isinya menyakiti & tidak perlu"],answer:2,explain:"Bertanya yang bijak juga tahu kapan diam: hormati waktu orang & jangan bertanya untuk melukai.",hint:"Ada saat untuk menahan pertanyaan, atau tanyakan semua selalu?"},
{n:94,type:"mcq",micro:"Kasus: pertanyaan menindaklanjuti komitmen",q:"Di akhir rapat, pertanyaan yang memastikan rencana benar-benar jalan:",options:["'Jadi, siapa mengerjakan apa, kapan selesai, & kapan kita cek lagi?'","'Semua paham ya?' lalu bubar","'Ada pertanyaan?' (tanpa merangkum tugas)"],answer:0,explain:"Pertanyaan penutup yang mengunci siapa-apa-kapan mengubah diskusi menjadi tindakan.",hint:"Kunci siapa-apa-kapan, atau 'semua paham ya'?"},
{n:95,type:"tf",micro:"Pertanyaan & rendah hati",q:"Benar atau Salah: Kebiasaan sering bertanya menunjukkan seseorang malas berpikir sendiri & terlalu bergantung pada orang lain.",answer:false,explain:"Sebaliknya, bertanya mencerminkan sikap rendah hati — mengakui kamu tidak tahu segalanya. Orang yang merasa sudah tahu semua justru berhenti belajar.",hint:"Bertanya = rendah hati, atau lemah?"},
{n:96,type:"mcq",micro:"Kasus: menyeimbangkan pertanyaan di percakapan santai",q:"Saat mengobrol santai dengan teman baru, keseimbangan yang nyaman:",options:["Hanya bicara tentang dirimu tanpa bertanya (terasa cuek)","Bertanya tentang dia, berbagi tentang dirimu juga, & membiarkan percakapan mengalir dua arah","Bertanya bertubi tanpa pernah berbagi tentang dirimu (terasa interogasi)"],answer:1,explain:"Percakapan yang enak adalah pertukaran: bertanya, mendengar, berbagi balik, bergantian.",hint:"Dua arah, atau interogasi / monolog?"},
{n:97,type:"mcq",micro:"Prinsip inti bab ini",q:"Pesan inti bertanya yang baik:",options:["Tahan semua pertanyaan agar tidak terlihat bodoh","Tembakkan pertanyaan sebanyak mungkin","Bertanya itu kekuatan, bukan kelemahan; buat pertanyaan spesifik & bisa dijawab, pilih terbuka/tertutup sesuai tujuan, jaga nada penasaran bukan menghakimi, simak jawabannya, & tahu kapan berhenti"],answer:2,explain:"Ringkasan: bertanya = belajar; spesifik & terjawab; jenis sesuai tujuan; nada penasaran; menyimak jawaban; peka kapan cukup.",hint:"Kekuatan, spesifik, jenis sesuai tujuan, nada penasaran, menyimak, tahu batas — rangkai."},
{n:98,type:"tf",micro:"Refleksi: pertanyaan & hubungan",q:"Benar atau Salah: Menunjukkan minat tulus lewat pertanyaan ('gimana kabarmu?', 'gimana lombanya kemarin?') & benar-benar menyimak jawabannya adalah salah satu cara paling sederhana mempererat hubungan.",answer:true,explain:"Orang merasa dihargai ketika seseorang cukup peduli untuk bertanya & mengingat jawabannya.",hint:"Bertanya + menyimak mempererat hubungan, atau tak berpengaruh?"},
{n:99,type:"mcq",micro:"Kasus: refleksi harian",q:"Cara melatih keterampilan bertanya lewat refleksi:",options:["Setelah percakapan penting, tanya diri: pertanyaan apa yang membantu? apa yang menyudutkan? pertanyaan apa yang seharusnya kutanyakan tapi tidak?","Tidak pernah mengevaluasi","Menganggap pertanyaan orang lain selalu salah"],answer:0,explain:"Meninjau pertanyaanmu sendiri mengubah tiap percakapan menjadi latihan bertanya yang lebih baik.",hint:"Evaluasi jujur, atau tidak pernah meninjau?"},
{n:100,type:"open",micro:"Refleksi & aturan pribadi bertanya",q:"Tulis 'aturan pribadi bertanya' berisi minimal 5 poin yang akan kamu pegang, masing-masing dengan alasan singkat.",sample:"Contoh aturan pribadi: (1) Kalau aku bingung, aku bertanya — setelah mencoba mencari sendiri untuk hal yang mudah — karena menyimpan kebingungan diam-diam lebih merugikan daripada bertanya. (2) Aku membuat pertanyaanku spesifik ('di langkah 3, kenapa dibagi 2?') alih-alih 'aku nggak ngerti' — karena pertanyaan spesifik mudah dijawab. (3) Aku memilih pertanyaan terbuka saat ingin orang bercerita, dan tertutup saat perlu memastikan satu fakta — karena tiap jenis punya kegunaan berbeda. (4) Aku menjaga nada penasaran, bukan menuduh, dan tidak memakai 'pertanyaan' untuk menyindir atau menghina — karena pertanyaan menghakimi menutup percakapan. (5) Setelah bertanya, aku diam sejenak memberi orang waktu berpikir, lalu benar-benar menyimak jawabannya — karena bertanya tanpa menyimak terasa seperti interogasi. (6) Aku berhenti menggali kalau orang terlihat tidak nyaman atau sudah menjawab jelas, dan aku boleh menolak menjawab pertanyaan yang terlalu pribadi. (7) Di akhir rapat/rencana, aku bertanya 'siapa-apa-kapan?' untuk memastikan rencana jadi tindakan.",explain:"Jawaban baik memuat minimal 5 aturan konkret dengan alasan, mencakup ide inti bab: berani bertanya (setelah coba sendiri untuk yang mudah), pertanyaan spesifik, pilih terbuka/tertutup sesuai tujuan, nada penasaran bukan menghakimi, beri jeda + simak jawaban, peka kapan berhenti / hak menolak menjawab, pertanyaan penutup siapa-apa-kapan.",hint:"Ambil satu pelajaran tiap fase — berani bertanya, spesifik, jenis sesuai tujuan, nada, simak, tahu batas — jadikan aturan 'aku akan...'."},
];
